using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
internal static partial class Catalog {
    static async Task<string> ReadProgress(System.Diagnostics.Process process,Action<string> progress){var text=new System.Text.StringBuilder();string line;while((line=await process.StandardOutput.ReadLineAsync().ConfigureAwait(false))!=null){if(text.Length<2000000)text.AppendLine(line);if(line.StartsWith("YUMA_PROGRESS:"))progress(line.Substring(14).Trim());}return text.ToString().Trim();}
}
internal partial class Player {
    readonly Dictionary<string,string> downloadProgress=new Dictionary<string,string>(),downloadPrefixes=new Dictionary<string,string>();
    readonly Dictionary<string,Track> failedDownloads=new Dictionary<string,Track>();
    long OfflineBytes(){if(!Directory.Exists(offlineRoot))return 0;long total=0;foreach(var f in new DirectoryInfo(offlineRoot).GetFiles())if((f.Attributes&FileAttributes.ReparsePoint)==0)total+=f.Length;return total;}
    void RecordDownloadProgress(string key,string text){if(closing||!IsHandleCreated)return;try{BeginInvoke((Action)delegate{if(!closing&&downloads.ContainsKey(key))downloadProgress[key]=text;});}catch(InvalidOperationException){}}
    static long ClearDisposableCache(string root){long bytes=0;foreach(string name in new[]{"artwork-cache-v1","canvas-cache"}){string folder=Path.Combine(root,name);if(!Directory.Exists(folder)||(File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0)continue;foreach(var f in new DirectoryInfo(folder).GetFiles()){if((f.Attributes&FileAttributes.ReparsePoint)!=0)continue;try{long size=f.Length;f.Delete();bytes+=size;}catch(IOException){}catch(UnauthorizedAccessException){}}}return bytes;}
    sealed class DownloadRow {internal string Key,Title,Detail;internal bool Busy,Failed;internal OfflineEntry Entry;public override string ToString(){return Title;}}
    void ShowDownloads(){using(var d=DialogUI.Create("Downloads & storage","See transfer progress, cancel a download or retry a failed song.",680,610)){
        var summary=DialogUI.Label(d,"",24,114,632,28,11,true);var list=new ListBox{Bounds=new Rectangle(24,156,632,282),BackColor=Theme.Ink,ForeColor=Theme.Paper,BorderStyle=BorderStyle.None,IntegralHeight=false,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=62,AccessibleName="Downloads"};d.Controls.Add(list);DarkScrollHost.Wrap(list).Visible=true;list.Visible=true;
        list.DrawItem+=delegate(object sender,DrawItemEventArgs e){if(e.Index<0)return;var item=(DownloadRow)list.Items[e.Index];var r=e.Bounds;r.Inflate(-2,-3);Fill(e.Graphics,r,12,(e.State&DrawItemState.Selected)!=0?Theme.Edge:Theme.Card);Glyph(e.Graphics,item.Busy?"\uE896":item.Failed?"\uE783":"\uE73E",new Rectangle(r.X+10,r.Y+14,30,30),Theme.Peach,18);TextAt(e.Graphics,item.Title,new Rectangle(r.X+52,r.Y+5,r.Width-64,24),11,Theme.Paper,true);TextAt(e.Graphics,item.Detail,new Rectangle(r.X+52,r.Y+31,r.Width-64,22),9,Theme.Muted);if((e.State&DrawItemState.Focus)!=0)e.DrawFocusRectangle();};
        var empty=new Surface{Bounds=new Rectangle(24,156,632,282),BackColor=Theme.Ink};empty.PaintSurface=delegate(Graphics g,Rectangle r){Fill(g,r,16,Theme.Card);Glyph(g,"\uE896",new Rectangle(r.Width/2-30,48,60,60),Theme.Peach,38);TextAt(g,"Your music, ready offline",new Rectangle(20,128,r.Width-40,35),18,Theme.Paper,true,true);TextAt(g,"Right-click a song and choose Save offline.\nTransfers and retry controls will appear here.",new Rectangle(28,174,r.Width-56,65),11,Theme.Muted,false,true,true);};d.Controls.Add(empty);
        Action refresh=delegate{int top=list.Items.Count>0?list.TopIndex:0;var selected=list.SelectedItem as DownloadRow;string key=selected==null?null:selected.Key;var rows=new List<DownloadRow>();foreach(var entry in offline.Where(x=>File.Exists(x.Path)))rows.Add(new DownloadRow{Key=entry.Key,Title=entry.Track.Title,Detail=(new FileInfo(entry.Path).Length/1048576.0).ToString("0.0")+" MB · Available offline",Entry=entry});foreach(var item in downloads){string progress;downloadProgress.TryGetValue(item.Key,out progress);rows.Add(new DownloadRow{Key=item.Key,Title=downloadNames[item.Key],Detail=string.IsNullOrEmpty(progress)?"Preparing transfer…":progress+" · Downloading",Busy=true});}foreach(var item in failedDownloads.Where(x=>!downloads.ContainsKey(x.Key)))rows.Add(new DownloadRow{Key=item.Key,Title=item.Value.Title,Detail="Download failed · Select and retry",Failed=true});list.BeginUpdate();list.Items.Clear();foreach(var row in rows)list.Items.Add(row);for(int i=0;i<list.Items.Count;i++)if(((DownloadRow)list.Items[i]).Key==key)list.SelectedIndex=i;if(list.Items.Count>0)list.TopIndex=Math.Min(top,list.Items.Count-1);list.EndUpdate();empty.Visible=rows.Count==0;if(empty.Visible)empty.BringToFront();summary.Text=rows.Count==0?"No downloads yet · Right-click a song → Save offline":(OfflineBytes()/1048576.0).ToString("0.0")+" MB used / "+featuresState.DownloadLimitMb+" MB limit · "+downloads.Count+" active";};
        DialogUI.Label(d,"Download storage limit (MB)",24,455,300,28,11,true);var limit=new ChoiceButton{Font=Theme.Font(10)};int[] sizes=new[]{512,2048,5120,10240,51200,featuresState.DownloadLimitMb}.Distinct().OrderBy(x=>x).ToArray();foreach(int size in sizes)limit.Items.Add(size+" MB");limit.SelectedIndex=Array.IndexOf(sizes,featuresState.DownloadLimitMb);limit.SetBounds(476,452,180,36);d.Controls.Add(limit);limit.SelectedIndexChanged+=delegate{featuresState.DownloadLimitMb=sizes[limit.SelectedIndex];SaveFeatures();};
        var action=new SoftButton("Cancel / retry",delegate{var row=list.SelectedItem as DownloadRow;if(row==null)return;if(row.Busy){CancellationTokenSource c;if(downloads.TryGetValue(row.Key,out c))c.Cancel();}else if(row.Failed){Track t;if(failedDownloads.TryGetValue(row.Key,out t))DownloadTrack(t);}refresh();});action.SetBounds(24,536,150,38);d.Controls.Add(action);
        var remove=new SoftButton("Remove copy",delegate{var row=list.SelectedItem as DownloadRow;if(row==null||row.Entry==null)return;if((Key(Current)==row.Key||string.Equals(Current.File,row.Entry.Path,StringComparison.OrdinalIgnoreCase))&&active){DialogUI.Show(d,"Stop this song before removing its offline copy.");return;}try{if(OwnedOffline(row.Entry.Path))File.Delete(row.Entry.Path);offline.Remove(row.Entry);SaveOffline();refresh();}catch(IOException ex){DialogUI.Show(d,ex.Message);}});remove.SetBounds(190,536,150,38);d.Controls.Add(remove);
        var clear=new SoftButton("Clear artwork cache",delegate{canvasUrl=null;long bytes=ClearDisposableCache(Path.Combine(Catalog.Root,"data"));DialogUI.Show(d,(bytes/1048576.0).ToString("0.0")+" MB cleared. Downloaded songs, lyrics and your library were kept.","Cache cleared");});clear.SetBounds(356,536,190,38);d.Controls.Add(clear);
        list.SelectedIndexChanged+=delegate{var row=list.SelectedItem as DownloadRow;action.Enabled=row!=null&&(row.Busy||row.Failed);remove.Enabled=row!=null&&row.Entry!=null;};action.Enabled=remove.Enabled=false;
        using(var timer=new System.Windows.Forms.Timer{Interval=750}){timer.Tick+=delegate{refresh();};refresh();timer.Start();d.ShowDialog(this);}
    }}
}
